        reset = 1;
        @(posedge clk);
        #1;
        if (q !== 10'd0) errors = errors + 1;

        reset = 0;
        // Cycle 0 (after reset deassertion on posedge)
        @(posedge clk); 
        #1;
        if (q !== 10'd1) errors = errors + 1;

        // Final result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
